patch:
diff --git a/src/inventory.js b/src/inventory.js
index 157e7bf..149acf2 100644
--- a/src/inventory.js
+++ b/src/inventory.js
@@ -39,6 +39,8 @@ export class Inventory {
   remove(id, quantity = 1) {
     const book = this.books.get(id)
     if (!book) throw new Error(`Unknown book: ${id}`)
+    if (!Number.isInteger(quantity) || quantity <= 0) throw new RangeError('quantity must be a positive integer')
+    if (quantity > book.stock) throw new RangeError('quantity exceeds current stock')
     book.stock -= quantity
     return book
   }
